fn outer(source map[string]int){fn captured(){print(unwrap(source["key"]),len(source))}
return captured}
fn main(){var source=map[string]int{"key":1}
let callback=outer(source)
source["key"]=9
source["extra"]=2
callback()}

import std.list as list
fn outer(source List<int>){fn captured(){print(unwrap(list.get(source,0)),list.len(source))}
return captured}
fn main(){var source=list.from_slice([1])
let callback=outer(source)
unwrap(list.set(source,0,9))
unwrap(list.append(source,2))
callback()}

import std.buffer as buffer
fn outer(source Buffer){fn captured(){print(unwrap(buffer.text(source)),buffer.len(source))}
return captured}
fn main(){var source=buffer.new()
unwrap(buffer.write_text(source,"a"))
let callback=outer(source)
unwrap(buffer.write_text(source,"b"))
callback()}

